//#region src/schema/define-table.ts
/** Canonical namespace order used by schema declarations and public exports. */
const gtfsNamespaces = [
	"gtfs-schedule",
	"gtfs-realtime",
	"gtfs-plus",
	"gtfs-ride",
	"gtfs-to-html",
	"noptis",
	"tods",
	"tides"
];
function validateDefinition(definition) {
	const tableName = definition.file ?? definition.table;
	const fieldNames = new Set(Object.keys(definition.fields));
	for (const primaryField of definition.primaryKey ?? []) if (!fieldNames.has(primaryField)) throw new Error(`Invalid GTFS table ${tableName}: primary key field ${primaryField} is not defined`);
	for (const constraint of definition.constraints ?? []) if (!fieldNames.has(constraint.startField) || !fieldNames.has(constraint.endField)) throw new Error(`Invalid GTFS table ${tableName}: range constraint references an unknown field`);
	for (const configuredIndex of definition.storage?.indexes ?? []) {
		const indexColumns = typeof configuredIndex === "string" ? [configuredIndex] : configuredIndex;
		for (const column of indexColumns) {
			const isGeneratedTimestamp = Object.entries(definition.fields).some(([fieldName, field]) => field.kind === "time" && (fieldName.endsWith("_time") ? `${fieldName}stamp` : `${fieldName}_timestamp`) === column);
			if (!fieldNames.has(column) && !isGeneratedTimestamp) throw new Error(`Invalid GTFS table ${tableName}: index field ${column} is not defined`);
		}
	}
}
/**
* Defines and validates one canonical GTFS table manifest.
*/
function defineGtfsTable(definition) {
	validateDefinition(definition);
	return definition;
}

