//#region src/schema/compile-table.ts
function storageKind(field) {
	if (field.kind === "id") return "text";
	if (field.kind === "enumeration") return typeof field.values[0] === "number" ? "integer" : "text";
	return field.kind;
}
function getTableName(definition) {
	if (definition.file === null) return definition.table;
	const extensionIndex = definition.file.lastIndexOf(".");
	return extensionIndex === -1 ? definition.file : definition.file.slice(0, extensionIndex);
}
function compileTable(definition) {
	const primaryFields = new Set(definition.primaryKey ?? []);
	const columns = Object.entries(definition.fields).map(([name, field]) => {
		return {
			...field,
			name,
			storageKind: storageKind(field),
			primaryKey: primaryFields.has(name),
			sqlMinimum: field.minimum,
			sqlMaximum: field.maximum
		};
	});
	return {
		...definition,
		name: getTableName(definition),
		columns
	};
}
function getTimestampColumnName(columnName) {
	return columnName.endsWith("time") ? `${columnName}stamp` : `${columnName}_timestamp`;
}
/** Returns the columns making up a table's declared key, in manifest order. */
function getPrimaryKeyColumns(table) {
	return table.columns.filter((column) => column.primaryKey);
}
